WITH KategoriCiro2025 AS (SELECT u.kategori, COALESCE(SUM(skl.adet * skl.birim_fiyat), 0.0) AS ciro_2025 FROM urunler u JOIN siparis_kalemleri skl ON u.id = skl.urun_id JOIN siparisler s ON skl.siparis_id = s.id WHERE s.tarih LIKE '2025-%' GROUP BY u.kategori), TumKategoriler AS (SELECT DISTINCT kategori FROM urunler), ToplamCiro2025 AS (SELECT COALESCE(SUM(ciro_2025), 0.0) AS toplam_ciro FROM KategoriCiro2025) SELECT tk.kategori, ROUND(COALESCE(kc.ciro_2025, 0.0), 2) AS ciro, ROUND((COALESCE(kc.ciro_2025, 0.0) * 100.0) / (SELECT toplam_ciro FROM ToplamCiro2025), 1) AS yuzde, DENSE_RANK() OVER (ORDER BY COALESCE(kc.ciro_2025, 0.0) DESC, tk.kategori ASC) AS sira FROM TumKategoriler tk LEFT JOIN KategoriCiro2025 kc ON tk.kategori = kc.kategori ORDER BY sira, tk.kategori ASC;